from collections import Counter

def pairs_sum_to_zero(l):
    """
    pairs_sum_to_zero takes a list of integers as an input.
    It returns True if there exist two distinct elements in the list
    that sum to zero, and False otherwise.
    """
    count = Counter(l)
    for num in count:
        if num == 0:
            # Need at least two zeros to form a pair (0 + 0)
            if count[num] >= 2:
                return True
        else:
            if -num in count:
                return True
    return False
