def hex_key(num: str) -> int:
    """
    Counts the number of prime-value hexadecimal digits in the input string.
    Valid prime digits in hexadecimal are: 2, 3, 5, 7, B (11), and D (13).
    """
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    return sum(1 for ch in num if ch in prime_hex_digits)

