import math

def count_up_to(n):
    """
    Returns a list of all prime numbers less than n, in ascending order.
    """
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        limit = int(math.sqrt(num)) + 1
        for i in range(3, limit, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)
    return primes
